sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    const data = event.payload.value;

    console.log('===== DATA =====');
    console.log('DATA SELECIONADA:', data);

    api.setState('selected_date', data);

    if (data) {
        api.data.look_up_multiple_records_reservas.refresh();

        console.log('Consulta de reservas atualizada pela DATA.');
    }
}
